+void UnlockApp::loadWidgets()
+{
+    const QStringList pluginIds = KScreenSaverSettingsBase::self()->widgets();
+    if (pluginIds.isEmpty()) {
+        return;
+    }
+
+    m_widgetsCorona = new WidgetsCorona(this);
+    m_widgetsCorona->setKPackage(m_shellIntegration->package());
+    // The widgets can't be configured from the lock screen, so always start from their defaults
+    m_widgetsCorona->config()->deleteGroup(QStringLiteral("Containments"));
+
+    Plasma::Containment *containment = m_widgetsCorona->createContainment(QStringLiteral("null"));
+    for (const QString &pluginId : pluginIds) {
+        if (QQuickItem *item = PlasmaQuick::AppletQuickItem::itemForApplet(containment->createApplet(pluginId))) {
+            m_widgetItems.append(item);
+        }
+    }
+
+    // QScreen doesn't know which output is the primary one on Wayland
+    connect(new KScreen::GetConfigOperation(KScreen::GetConfigOperation::NoEDID),
+            &KScreen::ConfigOperation::finished,
+            this,
+            [this](KScreen::ConfigOperation *op) {
+                const KScreen::ConfigPtr config = qobject_cast<KScreen::GetConfigOperation *>(op)->config();
+                if (config && config->primaryOutput()) {
+                    m_primaryOutputName = config->primaryOutput()->name();
+                    updateWidgetsView();
+                }
+            });
+}
