+
+void UnlockApp::updateWidgetsView()
+{
+    if (m_widgetItems.isEmpty() || m_views.isEmpty()) {
+        return;
+    }
+
+    // An applet item can only be shown once, so the widgets go on the primary screen
+    QQuickView *widgetsView = m_views.constFirst();
+    for (QQuickView *view : std::as_const(m_views)) {
+        if (view->screen()->name() == m_primaryOutputName) {
+            widgetsView = view;
+            break;
+        }
+    }
+    if (widgetsView == m_widgetsView) {
+        return;
+    }
+
+    if (m_widgetsView) {
+        QQmlProperty(m_widgetsView->rootObject(), QStringLiteral("widgets")).write(QVariant::fromValue(QList<QObject *>()));
+    }
+    m_widgetsView = widgetsView;
+    QQmlProperty(m_widgetsView->rootObject(), QStringLiteral("widgets")).write(QVariant::fromValue(m_widgetItems));
 }

