+QList<WidgetInfo> ScreenLockerKcm::availableWidgets() const
+{
+    QList<WidgetInfo> widgets;
+    const auto plugins = Plasma::PluginLoader::self()->listAppletMetaData(QString());
+    for (const KPluginMetaData &plugin : plugins) {
+        if (plugin.rawData().value(u"NoDisplay").toBool() || plugin.category() == QLatin1String("Containments")) {
+            continue;
+        }
+        widgets.append({plugin.name(), plugin.pluginId(), plugin.iconName()});
+    }
+    QCollator collator;
+    collator.setCaseSensitivity(Qt::CaseInsensitive);
+    std::sort(widgets.begin(), widgets.end(), [&collator](const WidgetInfo &w1, const WidgetInfo &w2) {
+        return collator.compare(w1.name, w2.name) < 0;
+    });
+    return widgets;
+}
